messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Walk / Run Cycle</title>
<style>
  html, body { margin: 0; height: 100%; overflow: hidden; background: #14161a; }
  canvas { display: block; }
  #hud {
    position: fixed; left: 24px; bottom: 20px;
    font-family: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
    font-size: 12px; letter-spacing: 0.18em; color: #8b93a1;
    text-transform: uppercase; user-select: none; pointer-events: none;
  }
  #hud b { color: #e8ecf2; font-weight: 600; }
</style>
</head>
<body>
<div id="hud">phase&nbsp;&nbsp;<b id="phase">stand</b>&nbsp;&nbsp;&nbsp;<span id="clock">0.0s</span> / 10.0s</div>
<script type="module">
import * as THREE from './three.module.js';

/* ---------- renderer / scene / camera ---------- */
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.setSize(innerWidth, innerHeight);
document.body.appendChild(renderer.domElement);

const scene = new THREE.Scene();
scene.background = new THREE.Color(0x14161a);
scene.fog = new THREE.Fog(0x14161a, 14, 30);

const camera = new THREE.PerspectiveCamera(42, innerWidth / innerHeight, 0.1, 100);
camera.position.set(0, 1.7, 6.5);
camera.lookAt(0, 1.05, 0);

addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});

/* ---------- lights ---------- */
scene.add(new THREE.HemisphereLight(0x9aa5b8, 0x2a2d33, 0.9));
const key = new THREE.DirectionalLight(0xfff4e0, 1.5);
key.position.set(4, 7, 5);
scene.add(key);
const rim = new THREE.DirectionalLight(0x6f7fa8, 0.7);
rim.position.set(-5, 4, -4);
scene.add(rim);

/* ---------- treadmill ground ---------- */
const ground = new THREE.Mesh(
  new THREE.BoxGeometry(4.4, 0.3, 14),
  new THREE.MeshStandardMaterial({ color: 0x23262c, roughness: 0.9 })
);
ground.position.y = -0.15;
scene.add(ground);

// belt stripes (scroll to imply motion while walking/running)
const beltMat = new THREE.MeshStandardMaterial({ color: 0x3a3f49, roughness: 0.6 });
const stripes = new THREE.Group();
for (let i = 0; i < 14; i++) {
  const s = new THREE.Mesh(new THREE.BoxGeometry(4.2, 0.02, 0.12), beltMat);
  s.position.set(0, 0.012, -6.5 + i);
  stripes.add(s);
}
scene.add(stripes);

// subtle lane edge
[-2.2, 2.2].forEach(x => {
  const e = new THREE.Mesh(
    new THREE.BoxGeometry(0.08, 0.06, 14),
    new THREE.MeshStandardMaterial({ color: 0x4a5160, roughness: 0.5 })
  );
  e.position.set(x, 0.03, 0);
  scene.add(e);
});

/* ---------- low-poly humanoid ---------- */
const matBody  = new THREE.MeshStandardMaterial({ color: 0xd8d2c4, roughness: 0.8, flatShading: true });
const matJoint = new THREE.MeshStandardMaterial({ color: 0x2f333b, roughness: 0.7, flatShading: true });
const matAccent= new THREE.MeshStandardMaterial({ color: 0xc4553a, roughness: 0.7, flatShading: true });

const root = new THREE.Group();          // whole body (lean applied here)
scene.add(root);

const hips = new THREE.Group();          // vertical bob applied here
hips.position.y = 1.02;
root.add(hips);

// torso
const torso = new THREE.Mesh(new THREE.BoxGeometry(0.42, 0.52, 0.24), matBody);
torso.position.y = 0.30;
hips.add(torso);

// head
const neck = new THREE.Mesh(new THREE.BoxGeometry(0.12, 0.1, 0.12), matJoint);
neck.position.y = 0.60;
hips.add(neck);
const head = new THREE.Mesh(new THREE.BoxGeometry(0.26, 0.26, 0.26), matBody);
head.position.y = 0.78;
hips.add(head);
const visor = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.07, 0.05), matAccent);
visor.position.set(0, 0.80, 0.14);
hips.add(visor);

/* limb builder: group at shoulder/hip pivot, two box segments */
function limb(len1, len2, thick, pivotY, pivotX, mat) {
  const g = new THREE.Group();
  g.position.set(pivotX, pivotY, 0);
  const upper = new THREE.Mesh(new THREE.BoxGeometry(thick, len1, thick), mat);
  upper.position.y = -len1 / 2;
  g.add(upper);
  const low = new THREE.Group();
  low.position.y = -len1;
  const lower = new THREE.Mesh(new THREE.BoxGeometry(thick * 0.9, len2, thick * 0.9), mat);
  lower.position.y = -len2 / 2;
  low.add(lower);
  const tip = new THREE.Mesh(new THREE.BoxGeometry(thick * 1.05, 0.08, thick * 1.6), matJoint);
  tip.position.set(0, -len2, 0.03);
  low.add(tip);
  g.add(low);
  return { g, low };
}

const armL = limb(0.34, 0.32, 0.11, 0.50,  0.27, matBody);
const armR = limb(0.34, 0.32, 0.11, 0.50, -0.27, matBody);
const legL = limb(0.44, 0.42, 0.13, 0.02,  0.13, matBody);
const legR = limb(0.44, 0.42, 0.13, 0.02, -0.13, matBody);
hips.add(armL.g, armR.g, legL.g, legR.g);

/* ---------- animation state ---------- */
const CYCLE = 10;
const STAND1 = 2, WALK = 3, RUN = 3;     // stand 0-2, walk 2-5, run 5-8, stand 8-10

const phaseEl = document.getElementById('phase');
const clockEl = document.getElementById('clock');
let lastPhase = '';

function setPose(t) {
  // which phase?
  let phase, ph;
  if (t < STAND1)            { phase = 'stand';  ph = 0; }
  else if (t < STAND1 + WALK){ phase = 'walk';   ph = (t - STAND1) / WALK; }
  else if (t < STAND1 + WALK + RUN){ phase = 'run'; ph = (t - STAND1 - WALK) / RUN; }
  else                       { phase = 'stand';  ph = 0; }

  let swingAmp, legAmp, freq, lean, bobAmp, bobFreq, elbow, kneeAmp, strideTwist;

  if (phase === 'walk') {
    swingAmp = 0.55; legAmp = 0.55; freq = 5.2; lean = 0.03;
    bobAmp = 0.025; bobFreq = freq * 2; elbow = 0.35; kneeAmp = 0.7; strideTwist = 0.06;
  } else if (phase === 'run') {
    swingAmp = 1.05; legAmp = 1.05; freq = 9.0; lean = 0.16;
    bobAmp = 0.06;  bobFreq = freq * 2; elbow = 1.15; kneeAmp = 1.5; strideTwist = 0.14;
  } else {
    swingAmp = 0; legAmp = 0; freq = 0; lean = 0;
    bobAmp = 0; bobFreq = 0; elbow = 0.12; kneeAmp = 0; strideTwist = 0;
  }

  const w = t * freq; // oscillator phase

  if (phase === 'stand') {
    // ease limbs back to neutral
    const ease = 0.12;
    armL.g.rotation.x += (0 - armL.g.rotation.x) * ease;
    armR.g.rotation.x += (0 - armR.g.rotation.x) * ease;
    legL.g.rotation.x += (0 - legL.g.rotation.x) * ease;
    legR.g.rotation.x += (0 - legR.g.rotation.x) * ease;
    armL.low.rotation.x += (-0.12 - armL.low.rotation.x) * ease;
    armR.low.rotation.x += (-0.12 - armR.low.rotation.x) * ease;
    legL.low.rotation.x += (0 - legL.low.rotation.x) * ease;
    legR.low.rotation.x += (0 - legR.low.rotation.x) * ease;
    hips.rotation.y += (0 - hips.rotation.y) * ease;
    hips.position.y += (1.02 - hips.position.y) * ease;
    root.rotation.x += (0 - root.rotation.x) * ease;
  } else {
    const s = Math.sin(w), c = Math.sin(w + Math.PI); // opposite limbs
    // legs: thigh swing, knee flex on recovery leg
    legL.g.rotation.x = s * legAmp;
    legR.g.rotation.x = c * legAmp;
    const kneeL = Math.max(0, Math.sin(w + 1.4)) * kneeAmp;
    const kneeR = Math.max(0, Math.sin(w + Math.PI + 1.4)) * kneeAmp;
    legL.low.rotation.x = kneeL;
    legR.low.rotation.x = kneeR;
    // arms: opposite to legs, elbows bent
    armL.g.rotation.x = c * swingAmp;
    armR.g.rotation.x = s * swingAmp;
    armL.low.rotation.x = -elbow - Math.max(0, c) * 0.35;
    armR.low.rotation.x = -elbow - Math.max(0, s) * 0.35;
    // torso counter-rotation + bob + lean
    hips.rotation.y = s * strideTwist;
    hips.position.y = 1.02 + Math.abs(Math.sin(w)) * bobAmp - 0.01;
    root.rotation.x = lean;
  }

  if (phase !== lastPhase) {
    lastPhase = phase;
    phaseEl.textContent = phase === 'run' ? 'run' : phase;
  }
  clockEl.textContent = t.toFixed(1) + 's';

  // belt scroll speed matches gait
  beltSpeed = phase === 'walk' ? 1.4 : phase === 'run' ? 3.6 : 0;
}

let beltSpeed = 0, beltOffset = 0;
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const dt = Math.min(clock.getDelta(), 0.05);
  const t = clock.elapsedTime % CYCLE;
  setPose(t);

  beltOffset = (beltOffset + beltSpeed * dt) % 1;
  stripes.children.forEach((s, i) => { s.position.z = -6.5 + ((i + beltOffset) % 14); });

  renderer.render(scene, camera);
}
animate();
</script>
</body>
</html>
```
